/**
 * The Mythroads engine, compiled from Lean.
 *
 * `proofs/Mythroads/Engine/**` is the definition of the game; `lake exe mythroads-compile`
 * translates the monomorphised compiler IR of `Mythroads.Engine.step` and everything it
 * reaches into the TypeScript below. Do not edit this file: run `npm run proofs:generate`.
 *
 * Representation:
 * - a Lean structure is a plain object;
 * - a many-constructor inductive is a union tagged with `_`, as in `{ _: "lobby" }`;
 * - `List` is an array, `Nat` and `Int` are `number`, `String` is `string`;
 * - `Option` is `{ _: "none" }` or `{ _: "some", val }`, never `undefined`.
 *
 * `step(state, envelope)` returns `Except<Error, Prod<State, Effect[]>>`: either
 * `{ _: "error", a: <error> }` or `{ _: "ok", a: { fst: <next state>, snd: <effects> } }`.
 * Both `Except` constructors name their payload `a` and `Prod` names its parts `fst` and
 * `snd`, because field names are Lean's binder names and nothing here renames them.
 * `step` is pure and total; the caller persists the effects and stores the new state.
 *
 * `tests/engine/engine-parity.test.ts` checks this file against the Lean `step` itself,
 * scenario by scenario and over a seeded fuzz, by exact JSON.
 */

/** Truncating `Nat` subtraction: Lean's `a - b` is `0` when `b` exceeds `a`. */
const natSub = (a: number, b: number): number => (a > b ? a - b : 0)

/** Lean's `Nat` division, which is `0` rather than an error when dividing by zero. */
const natDiv = (a: number, b: number): number => (b === 0 ? 0 : Math.floor(a / b))

/** Lean's `Nat` modulus, which is the dividend itself when the divisor is zero. */
const natMod = (a: number, b: number): number => (b === 0 ? a : a % b)

/** `String.toList`: the Unicode code points of a string, which is what a Lean `Char` is. */
const leanChars = (s: string): number[] => Array.from(s, (c) => c.codePointAt(0) ?? 0)

/** `String.ofList`: the inverse of `leanChars`. */
const leanString = (cs: number[]): string => cs.map((c) => String.fromCodePoint(c)).join('')

/** `String.Slice.trimAscii`: Lean trims exactly space, tab, carriage return and newline. */
const leanTrimAscii = (s: string): string => s.replace(/^[\t\n\r ]+/, '').replace(/[\t\n\r ]+$/, '')

/** The Unicode code point at a UTF-16 offset, which is what Lean's `decodeChar` returns. */
const leanCharAt = (s: string, index: number): number => s.codePointAt(index) ?? 0

/** How many UTF-16 code units a code point occupies, the unit this engine indexes in. */
const leanCharWidth = (c: number): number => (c > 0xffff ? 2 : 1)

/** `String.Pos.set`: replace the character at a UTF-16 offset. */
const leanCharSet = (s: string, index: number, c: number): string =>
    s.slice(0, index) +
    String.fromCodePoint(c) +
    s.slice(index + leanCharWidth(leanCharAt(s, index)))
