/** Lean `Mythroads.Engine.authorized`. */
export function authorized(s: State, env: Envelope): boolean {
    const env_1 = env
    const actor = env_1.actor
    const Event_authority_1 = Event_authority(env_1.event)
    switch (Event_authority_1._) {
        case 'account': {
            const scrutinee = actor === ''
            if (scrutinee) {
                return false
            } else {
                return true
            }
        }
        case 'roomHost': {
            const s_1 = s
            return s_1.host === actor
        }
        case 'playerOwner': {
            const subject = env_1.subject
            switch (subject._) {
                case 'none': {
                    return false
                }
                case 'some': {
                    const State_player_q_1 = State_player_q(s, subject.val)
                    switch (State_player_q_1._) {
                        case 'none': {
                            return false
                        }
                        case 'some': {
                            const val = State_player_q_1.val
                            return val.owner === actor
                        }
                    }
                    throw new Error('non-exhaustive match on Option')
                }
            }
            throw new Error('non-exhaustive match on Option')
        }
    }
    throw new Error('non-exhaustive match on Mythroads.Game.Events.Authority')
}

